<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
auth(true);$evento=(int)($_GET['event_id']??0);$buscar=trim($_GET['buscar']??'');$estado=trim($_GET['estado']??'');$where=['1=1'];$args=[];
if($evento){$where[]='r.event_id=?';$args[]=$evento;}if($estado!==''){$where[]='r.status=?';$args[]=$estado;}if($buscar!==''){$where[]="(CONCAT(r.first_name,' ',r.last_name) LIKE ? OR r.ci LIKE ?)";array_push($args,'%'.$buscar.'%','%'.$buscar.'%');}
$pagina=max(1,(int)($_GET['pagina']??1));$base=' FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where);$total=(int)q('SELECT COUNT(*)'.$base,$args)->fetchColumn();$filas=all('SELECT r.*,e.name evento_nombre'.$base.' ORDER BY r.id DESC LIMIT 50 OFFSET '.(($pagina-1)*50),$args);
headerPage('Anular / reactivar inscripciones'); ?>
<div class="card p-4"><p>Seleccione al participante para anular o reactivar su inscripción. El motivo y el administrador responsable quedan registrados en el historial. En grupos, la operación afecta a sus integrantes.</p><form method="get"><input type="hidden" name="p" value="gestion_inscripciones"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$evento);?></div><div class="col-md-4"><?php field('buscar','Participante / CI',$buscar,'text',false);?></div><div class="col-md-4"><?php selectField('estado','Estado',[''=>'Todos','Anulado'=>'Anuladas','Pendiente'=>'Pendiente','En revisión'=>'En revisión','Pagado'=>'Confirmadas','Rechazado'=>'Rechazadas'],$estado);?></div></div><button class="btn btn-primary">Buscar inscripciones</button></form></div>
<div class="card p-3"><p><?=e($total)?> inscripciones encontradas</p><div class="table-responsive"><table class="table"><tr><th>Registro</th><th>Participante</th><th>Evento</th><th>Inscrito por</th><th>Estado</th><th>Acción</th></tr><?php foreach($filas as $r):?><tr><td>#<?=e($r['id'])?></td><td><?=e(nombreParticipante($r))?><br>CI <?=e($r['ci'])?><?=$r['codigo_grupo']?'<br>Inscripción grupal':''?></td><td><?=e($r['evento_nombre'])?></td><td><?=e(responsableInscripcion($r))?></td><td><?=e($r['status'])?></td><td><a class="btn btn-sm <?=$r['status']==='Anulado'?'btn-success':'btn-outline-danger'?>" href="<?=url('p=participant&t='.$r['token'])?>"><?=$r['status']==='Anulado'?'Reactivar con motivo':'Anular con motivo'?></a></td></tr><?php endforeach?></table></div><div><?php if($pagina>1):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['pagina'=>$pagina-1])))?>">Anterior</a><?php endif?> Página <?=e($pagina)?><?php if($pagina*50<$total):?> <a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['pagina'=>$pagina+1])))?>">Siguiente</a><?php endif?></div></div><?php footerPage();
